Bash(powershell -Command "
\\$files = @\(
    'F:/GitHub/MazeGenerator/scripts/PACMAN_MAZE_GENERATION/PACMAN_MAZE_GENERATION.gml',
    'F:/GitHub/MazeGenerator/scripts/PACMAN_MAZE_WALLS_TUNNELS/PACMAN_MAZE_WALLS_TUNNELS.gml',
    'F:/GitHub/MazeGenerator/scripts/PACMAN_MAZE_TILE_MAP/PACMAN_MAZE_TILE_MAP.gml'
\)
foreach \(\\$f in \\$files\) {
    \\$c = Get-Content \\$f -Raw -Encoding UTF8
    \\$orig = \\$c
    \\$c = \\$c -replace 'CellDirection\\.UP', 'GRID_DIRECTION.UP'
    \\$c = \\$c -replace 'CellDirection\\.RIGHT', 'GRID_DIRECTION.RIGHT'
    \\$c = \\$c -replace 'CellDirection\\.DOWN', 'GRID_DIRECTION.DOWN'
    \\$c = \\$c -replace 'CellDirection\\.LEFT', 'GRID_DIRECTION.LEFT'
    if \(\\$c -ne \\$orig\) {
        Set-Content \\$f -Value \\$c -Encoding UTF8 -NoNewline
        Write-Host \\"Updated: \\$f\\"
    } else {
        Write-Host \\"No changes: \\$f\\"
    }
}")

